question:
Build a search autocomplete in React (or plain JavaScript), in the code box:

- after at least 2 characters, fetch suggestions with `search(query, signal)`, which returns `Promise<string[]>`;
- don't send a request for every keystroke while the user is typing;
- a slow old response that arrives after a newer one must not overwrite the newer results;
- keyboard support: arrow keys move the highlight, Enter picks, Escape closes;
- screen-reader users can tell how many suggestions there are and which one is highlighted.

Describe your state first, then write the code.

questions.solution:
```jsx
function Autocomplete({ search, onPick }) {
  const [query, setQuery] = useState('');
  const [items, setItems] = useState([]);
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(-1);
  const picked = useRef(null);

  useEffect(() => {
    if (query === picked.current) return; // just picked: don't fetch and reopen
    if (query.trim().length < 2) {
      setItems([]);
      return;
    }
    const controller = new AbortController();
    const timer = setTimeout(() => {
      search(query, controller.signal)
        .then((found) => {
          setItems(found);
          setActive(-1);
          setOpen(true);
        })
        .catch(() => {}); // aborted or failed: keep the old list
    }, 250);
    // The next keystroke clears the timer and aborts the request in flight.
    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [query, search]);

  const pick = (value) => {
    picked.current = value;
    setQuery(value);
    setOpen(false);
    onPick(value);
  };
  const onKeyDown = (e) => {
    if (!open || !items.length) return;
    if (e.key === 'ArrowDown') { e.preventDefault(); setActive((i) => (i + 1) % items.length); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); setActive((i) => (i <= 0 ? items.length - 1 : i - 1)); }
    else if (e.key === 'Enter' && active >= 0) { e.preventDefault(); pick(items[active]); }
    else if (e.key === 'Escape') setOpen(false);
  };

  return (
    <div>
      <input
        role="combobox"
        aria-expanded={open}
        aria-controls="ac-list"
        aria-autocomplete="list"
        aria-activedescendant={active >= 0 ? `ac-${active}` : undefined}
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        onKeyDown={onKeyDown}
      />
      <p aria-live="polite" className="sr-only">{open ? `${items.length} suggestions` : ''}</p>
      {open && (
        <ul id="ac-list" role="listbox">
          {items.map((item, i) => (
            <li key={item} id={`ac-${i}`} role="option" aria-selected={i === active}
                onMouseDown={(e) => e.preventDefault()} onClick={() => pick(item)}>
              {item}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
```

The effect cleanup is both the debounce and the race fix: a newer query clears the pending timer and aborts the older request, so its result can never land. Picking a suggestion sets the query too; without the `picked` check that change would fetch again and reopen the list 250 ms after the pick. `onMouseDown` with `preventDefault` keeps focus in the input when clicking an option. The input needs a visible `<label>` too.

question:
Build a tabs component (React or plain JavaScript, in the code box). The input is `[{ id, label, content }]`:

- clicking a tab shows its panel;
- keyboard: Left and Right move between tabs (wrapping), Home and End jump to the first and last;
- Tab moves from the tab list straight into the current panel rather than through every tab;
- a screen reader announces the tab's position, the count and whether it is selected.

When should arrow keys switch tabs immediately, and when should they only move focus, with Enter or Space to switch?

questions.solution:
```jsx
function Tabs({ tabs }) {
  const [selected, setSelected] = useState(0);
  const refs = useRef([]);
  const select = (i) => {
    const next = (i + tabs.length) % tabs.length;
    setSelected(next);
    refs.current[next].focus();
  };
  const onKeyDown = (e) => {
    const moves = { ArrowRight: selected + 1, ArrowLeft: selected - 1, Home: 0, End: tabs.length - 1 };
    if (e.key in moves) {
      e.preventDefault();
      select(moves[e.key]);
    }
  };
  return (
    <div>
      <div role="tablist" aria-label="Sections" onKeyDown={onKeyDown}>
        {tabs.map((tab, i) => (
          <button
            key={tab.id}
            ref={(el) => (refs.current[i] = el)}
            role="tab"
            id={`tab-${tab.id}`}
            aria-selected={i === selected}
            aria-controls={`panel-${tab.id}`}
            tabIndex={i === selected ? 0 : -1}
            onClick={() => setSelected(i)}
          >
            {tab.label}
          </button>
        ))}
      </div>
      {tabs.map((tab, i) => (
        <div key={tab.id} role="tabpanel" id={`panel-${tab.id}`} aria-labelledby={`tab-${tab.id}`}
             tabIndex={0} hidden={i !== selected}>
          {tab.content}
        </div>
      ))}
    </div>
  );
}
```

Screen readers derive "tab 2 of 4, selected" from the roles and `aria-selected`; no extra text is needed. This version activates on arrow keys (automatic activation), fine when panels are already rendered. If showing a panel triggers a fetch, move focus only and switch on Enter or Space (manual activation). Keeping hidden panels mounted with `hidden` preserves their state.

```jsx
function VirtualList({ items, rowHeight, height, renderRow, overscan = 5 }) {
  const [scrollTop, setScrollTop] = useState(0);
  const total = items.length * rowHeight;
  const start = Math.max(0, Math.floor(scrollTop / rowHeight) - overscan);
  const end = Math.min(items.length, Math.ceil((scrollTop + height) / rowHeight) + overscan);
  const rows = [];
  for (let i = start; i < end; i++) {
    rows.push(
      <div key={i} role="listitem" aria-setsize={items.length} aria-posinset={i + 1}
           style={{ position: 'absolute', top: i * rowHeight, height: rowHeight, left: 0, right: 0 }}>
        {renderRow(items[i], i)}
      </div>,
    );
  }
  return (
    <div style={{ height, overflowY: 'auto', position: 'relative' }}
         onScroll={(e) => setScrollTop(e.currentTarget.scrollTop)}>
      <div role="list" style={{ height: total, position: 'relative' }}>{rows}</div>
    </div>
  );
}
```

With 480 / 32 = 15 visible rows and 5 overscan on each side, about 25 rows are in the DOM at once. The scroll handler only stores `scrollTop`; React re-renders a few dozen rows, which is cheap. Variable heights: start from an estimate, measure rendered rows (a ResizeObserver), keep an array of prefix sums `top[i]`, find `start` with a binary search on `scrollTop`, and set the spacer to the sum of all heights.

question:
Build a confirmation dialog `ConfirmDialog({ open, title, onConfirm, onClose })` (React or plain JavaScript, in the code box):

- when it opens, focus moves into it, and Tab cycles inside it;
- Escape and a click on the backdrop close it;
- when it closes, focus returns to the button that opened it;
- while it is open, screen readers can't reach the page behind it and that page doesn't scroll.

You may use the native `<dialog>` element, but say what it does for you and what you still handle yourself.

questions.solution:
```jsx
function ConfirmDialog({ open, title, children, onConfirm, onClose }) {
  const ref = useRef(null);
  useEffect(() => {
    const dialog = ref.current;
    if (!open) return;
    const opener = document.activeElement;
    dialog.showModal();
    document.body.style.overflow = 'hidden';
    return () => {
      dialog.close();
      document.body.style.overflow = '';
      opener?.focus?.();
    };
  }, [open]);
  return (
    <dialog
      ref={ref}
      aria-labelledby="confirm-title"
      onCancel={(e) => { e.preventDefault(); onClose(); }}
      onClick={(e) => { if (e.target === ref.current) onClose(); }}
    >
      <h2 id="confirm-title">{title}</h2>
      {children}
      <button type="button" autoFocus onClick={onClose}>Cancel</button>
      <button type="button" onClick={onConfirm}>Delete</button>
    </dialog>
  );
}
```

`showModal()` puts the dialog in the top layer, makes everything else inert (no focus, hidden from assistive technology), moves focus inside (to the `autofocus` element here) and fires `cancel` on Escape. Preventing `cancel`'s default and calling `onClose` keeps the parent's `open` state the single source of truth. Still on you: restoring focus to the opener (the cleanup above), the backdrop click (a click on the `::backdrop` targets the `<dialog>` itself, and so does one on the dialog's own padding, so put the padding on an inner wrapper to keep the check exact), and locking background scroll.

question:
Build an infinite-scroll feed (React or plain JavaScript, in the code box). The backend is `fetchPage(cursor)`, returning `{ items, nextCursor }`, with `nextCursor === null` when there is nothing more:

- load the next page automatically as the user nears the bottom;
- only one request in flight at a time, and never the same page twice;
- on failure, show the error and a Retry button;
- show an end-of-feed message when there is nothing more;
- keyboard-only users can load more too.

Why a cursor here rather than page numbers?

questions.solution:
```jsx
function Feed({ fetchPage, renderItem }) {
  const [items, setItems] = useState([]);
  const [cursor, setCursor] = useState(undefined); // undefined: first page; null: the end
  const [status, setStatus] = useState('idle');    // idle | loading | error
  const loading = useRef(false);
  const sentinel = useRef(null);

  const loadMore = useCallback(async () => {
    if (loading.current || cursor === null) return;
    loading.current = true;
    setStatus('loading');
    try {
      const page = await fetchPage(cursor);
      setItems((old) => {
        const seen = new Set(old.map((item) => item.id));
        return [...old, ...page.items.filter((item) => !seen.has(item.id))];
      });
      setCursor(page.nextCursor);
      setStatus('idle');
    } catch {
      setStatus('error');
    } finally {
      loading.current = false;
    }
  }, [cursor, fetchPage]);

  useEffect(() => {
    const el = sentinel.current;
    if (!el || status === 'error') return;
    const observer = new IntersectionObserver(
      ([entry]) => entry.isIntersecting && loadMore(),
      { rootMargin: '400px' },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [loadMore, status]);

  return (
    <section aria-busy={status === 'loading'}>
      <ul>{items.map((item) => <li key={item.id}>{renderItem(item)}</li>)}</ul>
      <div ref={sentinel} />
      <p aria-live="polite">
        {status === 'loading' ? 'Loading…' : status === 'error' ? "Couldn't load more posts." : cursor === null ? "You're all caught up." : ''}
      </p>
      {cursor !== null && status !== 'loading' && (
        <button type="button" onClick={loadMore}>{status === 'error' ? 'Retry' : 'Load more'}</button>
      )}
    </section>
  );
}
```

The ref guard closes the gap between two observer callbacks firing before React re-renders. On error the observer is disconnected, so it doesn't retry in a loop; the button retries. Dedupe by id handles posts that shift across pages. For very long feeds, combine with virtualization.

question:
Build `DataTable({ rows, columns })` (React or plain JavaScript, in the code box), with `columns` like `[{ key: 'name', label: 'Name', type: 'string' }, { key: 'salary', label: 'Salary', type: 'number' }]`:

- clicking a column header sorts by it, and again reverses; number columns sort numerically, strings by locale rules;
- one text box filters on every string column;
- pagination at 20 rows a page;
- the sort state is exposed to screen readers and the headers work from the keyboard.

What do you keep in state, and what do you derive while rendering?

questions.solution:
```jsx
const collator = new Intl.Collator(undefined, { numeric: true, sensitivity: 'base' });
const PAGE = 20;

function DataTable({ rows, columns }) {
  const [sort, setSort] = useState({ key: null, dir: 1 });
  const [filter, setFilter] = useState('');
  const [page, setPage] = useState(0);

  const shown = useMemo(() => {
    const text = filter.trim().toLowerCase();
    const strings = columns.filter((c) => c.type === 'string');
    let out = text
      ? rows.filter((row) => strings.some((c) => String(row[c.key] ?? '').toLowerCase().includes(text)))
      : rows.slice();
    const column = columns.find((c) => c.key === sort.key);
    if (column) {
      const compare = column.type === 'number'
        ? (a, b) => (a ?? -Infinity) - (b ?? -Infinity)
        : (a, b) => collator.compare(String(a ?? ''), String(b ?? ''));
      out.sort((a, b) => sort.dir * compare(a[column.key], b[column.key]));
    }
    return out;
  }, [rows, columns, filter, sort]);

  const pages = Math.max(1, Math.ceil(shown.length / PAGE));
  const current = Math.min(page, pages - 1);
  const toggle = (key) => setSort((s) => ({ key, dir: s.key === key ? -s.dir : 1 }));

  return (
    <>
      <label>Filter <input value={filter} onChange={(e) => { setFilter(e.target.value); setPage(0); }} /></label>
      <table>
        <caption>Employees, {shown.length} rows</caption>
        <thead>
          <tr>
            {columns.map((c) => (
              <th key={c.key} scope="col"
                  aria-sort={sort.key === c.key ? (sort.dir === 1 ? 'ascending' : 'descending') : undefined}>
                <button type="button" onClick={() => toggle(c.key)}>{c.label}</button>
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {shown.slice(current * PAGE, current * PAGE + PAGE).map((row, i) => (
            <tr key={row.id ?? i}>{columns.map((c) => <td key={c.key}>{row[c.key]}</td>)}</tr>
          ))}
        </tbody>
      </table>
      <nav aria-label="Pages">
        <button type="button" disabled={current === 0} onClick={() => setPage(current - 1)}>Previous</button>
        <span>Page {current + 1} of {pages}</span>
        <button type="button" disabled={current >= pages - 1} onClick={() => setPage(current + 1)}>Next</button>
      </nav>
    </>
  );
}
```

`rows.slice()` copies before the in-place sort; `Array.prototype.sort` is stable since ES2019, so equal values keep their order. The page is clamped while rendering, so a shrinking result never shows an empty page.
